@php $photos=array_values(array_filter($item['items']??[],fn($photo)=>P::media($photo['media']??null)&&str_starts_with($photo['media']['mime_type']??'','image/'))); @endphp
<div x-data="{grid:'grid'}"><div class="gallery-toolbar"><p>{{ P::number(count($photos)) }} {{ P::t('رسانه') }}</p><div><button type="button" :aria-pressed="grid==='grid'" @click="grid='grid'">{{ P::t('نمای شبکه‌ای') }}</button><button type="button" :aria-pressed="grid==='large'" @click="grid='large'">{{ P::t('نمای بزرگ') }}</button></div></div>@if(!$photos)<p class="quiet">{{ P::t('رسانه‌ای برای این آلبوم اضافه نشده است.') }}</p>@endif<div class="gallery-masonry" :class="grid">@foreach($photos as $photo)<button class="gallery-tile" type="button" aria-label="{{ P::t('نمایش').' '.($photo['caption']?:P::t('رسانه').' '.P::number($loop->iteration)) }}" @click="openAlbum({{ \Illuminate\Support\Js::from($photos) }},{{ $loop->index }})"><img src="{{ P::media($photo['media']) }}" alt="{{ $photo['caption']?:P::t('تصویر آلبوم') }}" loading="lazy"><span><x-icon name="maximize" size="17" />{{ $photo['caption']?:P::t('مشاهده رسانه') }}</span></button>@endforeach</div></div>
